#: Every effect by template id.
def _from_the_database() -> int:
    """Replace the generated tables with the client's own, when it is there.

    The generated ones are a snapshot taken through a filter -- 458 of the database's
    6,703 status effects, being those a class skill names plus what their auras reach.
    Everything else was unknown to this server, which cannot serve five classes, and a
    snapshot also drifts against elements extracted from a different build.

    Loading is safe on the index question: the wire index is ``rowid - 1``, the rowids
    of every table used here run 1..N with no gaps, and index 1350 comes back as
    ``a0001_tutorial_heal_on_low_health`` -- which is the effect the recorded 0x004F
    carries. So this widens the table without moving anything already in it.

    Returns how many effects were loaded, or 0 when the file is absent and the
    generated tables stand.
    """
    from dsor import database

    columns = (
        "Id", "StatusEffectDuration", "StatusEffectTickRate", "MaxStackSize",
        "StartModifiers", "TickModifiers", "StopModifiers", "DoneModifiers",
        "ExclusiveGroup", "Groups", "StartSequence", "TickSequence",
        "StartAnimation", "AuraEffectId", "AuraRadius", "AuraTargets",
    )
    found = database.rows("_Template_StatusEffect", *columns)
    if not found:
        return 0

    def text(value):
        return "" if value is None else str(value)

    def number(value):
        return 0.0 if value is None else float(value)

    for row in found:
        index, values = row[0], row[1:]
        EFFECTS[index] = Effect(
            index,
            text(values[0]),
            number(values[1]),
            number(values[2]),
            0 if values[3] is None else int(values[3]),
            *(text(v) for v in values[4:13]),
            text(values[13]),
            number(values[14]),
            text(values[15]),
        )

    # The three lists a skill carries, and the tooltip's own word on what it does.
    for index, user, victim in database.rows(
        "_Template_Skill", "UserStatusEffects", "VictimStatusEffects"
    ):
        SKILL_EFFECTS[index] = (text(user), text(victim))
    for index, where in database.rows("_Template_Skill", "LocationStatusEffects"):
        if text(where):
            SKILL_LOCATIONS[index] = text(where)

    held = database.connection()
    tokens = held.execute(
        "SELECT DISTINCT Param1Id, Param1Attr, Param2Id FROM _Template_LocaleToken"
        " WHERE TokenType = 'SkillEffect' AND Param1Id <> '' AND Param2Id <> ''"
    ).fetchall()
    wire_of_skill = {
        row[1]: row[0] - database.ROW_TO_INDEX
        for row in held.execute("SELECT rowid, Id FROM _Template_Skill")
    }
    promised: dict[int, set] = {}
    for skill, kind, effect_id in tokens:
        wire = wire_of_skill.get(skill)
        if wire is not None:
            promised.setdefault(wire, set()).add((kind, effect_id))
    for wire, pairs in promised.items():
        PROMISED[wire] = tuple(sorted(pairs))
    return len(found)


#: How many effects the tables actually hold: 6703 with the database, 458 without.
LOADED = _from_the_database()

BY_ID: dict[str, Effect] = {e.id: e for e in EFFECTS.values()}


def effect(wire: int | None) -> Effect | None:
    return None if wire is None else EFFECTS.get(wire)


def by_id(name: str) -> Effect | None:
    return BY_ID.get(name)


def wire_of(name: str) -> int | None:
    found = BY_ID.get(name)
    return None if found is None else found.wire


def promised_by(skill_wire: int, kind: str) -> tuple[str, ...]:
    """The effect ids the skill's own tooltip names for *kind*.

    ``UserEffect``, ``VictimEffect`` or ``LocationEffect``. Empty when the skill has no
    token of that kind, which for a great many skills means it advertises no effect at
    all -- mightybash's tooltip names only a damage range, so it promises no stun.
    """
    return tuple(
        effect_id
        for token_kind, effect_id in PROMISED.get(skill_wire, ())
        if token_kind == kind
    )


def granted_by(skill_wire: int) -> tuple[Entry, ...]:
    """The effects the skill at *skill_wire* puts on its user.

    Only the ones that apply unconditionally and actually change something. A
    skill's list is mostly entries with a chance of 0.0 -- item procs, talents,
    set bonuses -- so warshout names sixteen effects and grants three.
    """
    return _certain(
        SKILL_EFFECTS.get(skill_wire), 0,
        promised=promised_by(skill_wire, "UserEffect"),
    )


def inflicted_by(skill_wire: int) -> tuple[Entry, ...]:
    """The effects the skill at *skill_wire* puts on its victims."""
    return _certain(
        SKILL_EFFECTS.get(skill_wire), 1,
        promised=promised_by(skill_wire, "VictimEffect"),
    )


def anything_by(skill_wire: int, victim: bool = False) -> tuple[Entry, ...]:
    """Every effect the skill names, chance or no chance.

    A chance of 0.0 marks the entries gated behind an item, a talent or a set bonus,
    and the warrior's stun and poison are among them: laceratingstrike's
    debuff_cc_stun and mightybash's debuff_dot_poison both read C:0.0. Faithfully they
    never fire without the talent that raises the chance, and this server has no
    talents -- so this exists to be able to exercise them, and the switch that uses it
    is off by default.
    """
    return _certain(SKILL_EFFECTS.get(skill_wire), 1 if victim else 0, gated=True)


def _certain(
    packed: tuple[str, str] | None,
    which: int,
    gated: bool = False,
    promised: tuple[str, ...] = (),
) -> tuple[Entry, ...]:
    if packed is None:
        return ()
    out = []
    for entry in parse_entries(packed[which]):
        # The union of the two statements the client makes, not one or the other.
        #
        # An entry applies if the tooltip names it *or* its chance is 1.0. Both are
        # the client's own words about the same skill and they cover different
        # ground: the tooltip names effects whose C: reads 0.0 (Ground Breaker's
        # armour break, Rageful Swing's damage debuff), and C:1.0 marks effects the
        # tooltip does not bother to mention (Ground Breaker's *stun*, Bloody Wild
        # Swing's bleed, Charge's stun).
        #
        # Making the tooltip the sole authority was a half-fix that then subtracted.
        # It was introduced to stop C: being read as a chance -- which it is not --
        # and it did stop that, but it also threw away every certain effect the
        # tooltip is silent about: five of the warrior's, including the stun that is
        # the whole point of Ground Breaker. Adding on the tooltip's word is right;
        # removing on its silence is not.
        #
        # The noise this lets in is already handled downstream: ctfdropflag carries a
        # PVPEventModifier and fails servable(), and skill_battlecry_impact_visualizer
        # changes nothing and fails changes_anything.
        if not (gated or entry.certain or entry.effect in promised):
            continue
        found = BY_ID.get(entry.effect)
        if found is None or not found.changes_anything:
            continue
        out.append(entry)
    return tuple(out)
